import { MELA_SCHEDULE_SNAPSHOT, type Mela, type MelaDay } from './mela-schedule.generated';
import { isEditorialFieldDisplayable, nativeCalendarDayDistance } from './observance-series-card-helpers';
import type { LocalizedEditorialField } from './observance-series-contract.generated';
import type { SacredDaysObservance } from './sacred-days-deck';

// Kumbh dates come from the state Mela authorities (lib/mela-schedule.generated.ts,
// generated by the backend). This module only selects and labels them: it never
// calculates a mela date, and an unconfirmed day is never shown (AGENTS.md section 2).

export const MELA_ROUTE_KIND = 'mela';

/** The traditions a mela card is offered to. Kumbh is a Hindu gathering; a guest (no tradition) sees it too. */
export function melaVisibleForTradition(melaTradition: string, profileTradition: string | null | undefined): boolean {
  if (!profileTradition || profileTradition === 'all' || profileTradition === 'neutral') return true;
  return profileTradition === melaTradition;
}

/** Today's civil date at the mela (its dates are civil dates in its own time zone, not the viewer's). */
export function civilDateIn(timeZone: string, now: Date = new Date()): string {
  const parts = new Intl.DateTimeFormat('en-CA', { timeZone, year: 'numeric', month: '2-digit', day: '2-digit' }).formatToParts(now);
  const get = (type: string) => parts.find((p) => p.type === type)?.value ?? '';
  return `${get('year')}-${get('month')}-${get('day')}`;
}

type MelaLang = 'en' | 'hi' | 'pa';

/**
 * A mela's text is scoped to the mela's own tradition (applicability.traditions), so the shared editorial gate needs
 * that tradition as its context; without it every scoped field is hidden (resolveFestivalText passes none).
 * Withheld, pending or unsourced text still resolves to '' and a pending translation falls back to English.
 */
export function melaText(mela: Mela, field: LocalizedEditorialField<{ en: string; hi?: string; pa?: string }> | undefined, lang: MelaLang): string {
  if (!field || !isEditorialFieldDisplayable(field, { tradition: mela.tradition })) return '';
  if (lang !== 'en' && field.value[lang] && field.translationStatus?.[lang] !== 'pending') return field.value[lang] ?? '';
  return field.translationStatus?.en === 'pending' ? '' : field.value.en || '';
}

export function melaList(mela: Mela, field: LocalizedEditorialField<{ en: string[]; hi?: string[]; pa?: string[] }> | undefined, lang: MelaLang): string[] {
  if (!field || !isEditorialFieldDisplayable(field, { tradition: mela.tradition })) return [];
  if (lang !== 'en' && field.value[lang]?.length && field.translationStatus?.[lang] !== 'pending') return field.value[lang] ?? [];
  return field.translationStatus?.en === 'pending' ? [] : field.value.en || [];
}

export function publishedMelaDays(mela: Mela): MelaDay[] {
  return mela.days.filter((day) => day.status === 'confirmed');
}

export function isAmritSnan(day: MelaDay): boolean {
  return day.kind === 'amrit_snan' || day.kind === 'principal_amrit_snan';
}

export function melaHref(slug: string): string {
  return `/mela/${encodeURIComponent(slug)}`;
}

export function findMela(slug: string, melas: readonly Mela[] = MELA_SCHEDULE_SNAPSHOT.melas): Mela | null {
  return melas.find((mela) => mela.slug === slug) ?? null;
}

/**
 * The next confirmed bathing day of each visible mela within `windowDays`, as
 * Home sacred-day entries. Ceremonies such as the flag hoisting are left to the
 * detail page; Home lists bathing days only.
 */
export function upcomingMelaObservances({
  profileTradition,
  windowDays,
  now = new Date(),
  melas = MELA_SCHEDULE_SNAPSHOT.melas,
}: {
  profileTradition: string | null | undefined;
  windowDays: number;
  now?: Date;
  melas?: readonly Mela[];
}): SacredDaysObservance[] {
  const entries: SacredDaysObservance[] = [];
  for (const mela of melas) {
    if (!melaVisibleForTradition(mela.tradition, profileTradition)) continue;
    const name = melaText(mela, mela.name, 'en');
    if (!name) continue;
    const today = civilDateIn(mela.timezone, now);
    for (const day of publishedMelaDays(mela)) {
      if (day.kind === 'event') continue;
      const daysLeft = nativeCalendarDayDistance(today, day.date);
      if (daysLeft === null || daysLeft < 0 || daysLeft > windowDays) continue;
      // The day's own title ("Maha Shivaratri") would read as the festival card beside it, so the
      // card names the Kumbh bath and the description carries the day and the place.
      entries.push({
        name: isAmritSnan(day) ? 'Kumbh Amrit Snan' : 'Kumbh Snan',
        emoji: mela.emoji,
        daysLeft,
        routeKind: MELA_ROUTE_KIND,
        routeSlug: mela.slug,
        href: melaHref(mela.slug),
        label: name,
        description: `${day.title}, ${day.place}`,
      });
      break;
    }
  }
  return entries;
}
